[metadata] {"filePath": "/workspace/repo/crates/polars-core/src/series/into.rs", "oldString": "pub(super) fn to_owned_dtype(field: Cow<ArrowField>) -> ArrowDataType {", "newString": "/// Converts a `Binary` (physically a `BinaryViewArray`) to a `FixedSizeBinary` array of the given
/// `size`. Null values are preserved, and non-null values must have a byte length equal to `size`.
fn binview_to_fixed_size_binary(
    array: &dyn Array,
    size: usize,
    arrow_dtype: ArrowDataType,
) -> PolarsResult<Box<dyn Array>> {
    use arrow::array::{BinaryViewArray, FixedSizeBinaryArray};
    use arrow::bitmap::MutableBitmap;

    let arr: &BinaryViewArray = array.as_any().downcast_ref().unwrap();
    let len = arr.len();

    let mut values: Vec<u8> = Vec::with_capacity(len * size);
    let mut validity: Option<MutableBitmap> = if arr.null_count() > 0 {
        Some(MutableBitmap::with_capacity(len))
    } else {
        None
    };

    for (i, opt_v) in arr.iter().enumerate() {
        match opt_v {
            Some(v) => {
                polars_ensure!(
                    v.len() == size,
                    ComputeError:
                    "bytes at index {i} had mismatching length {}", v.len(),
                );
                values.extend_from_slice(v);
                if let Some(validity) = validity.as_mut() {
                    validity.push(true);
                }
            },
            None => {
                values.resize(values.len() + size, 0);
                if let Some(validity) = validity.as_mut() {
                    validity.push(false);
                }
            },
        }
    }

    Ok(Box::new(FixedSizeBinaryArray::try_new(
        arrow_dtype,
        values.into(),
        validity.map(|v| v.freeze()),
