145	            }
146	            .run(),
147	        ));
148	
149	        Ok(async_executor::spawn(TaskPriority::Low, async move {
150	            compute_handle.await?;
151	            io_handle.await.unwrap()?;
152	            Ok(())
153	        }))
154	    }
155	}
